CREATE TABLE IF NOT EXISTS "DeliveryEmergencyOverride" ("id" UUID NOT NULL,"assessmentId" UUID NOT NULL,"pipelineId" UUID NOT NULL,"actorId" VARCHAR(120) NOT NULL,"reason" VARCHAR(2000) NOT NULL,"incidentReference" VARCHAR(255) NOT NULL,"confirmationToken" VARCHAR(128) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"status" VARCHAR(32) NOT NULL,"postReviewRequired" BOOLEAN NOT NULL DEFAULT true,"postReviewDueAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"consumedAt" TIMESTAMP(3),CONSTRAINT "DeliveryEmergencyOverride_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "DeliveryEmergencyOverride_assessmentId_status_idx" ON "DeliveryEmergencyOverride"("assessmentId","status");
CREATE INDEX IF NOT EXISTS "DeliveryEmergencyOverride_pipelineId_expiresAt_idx" ON "DeliveryEmergencyOverride"("pipelineId","expiresAt");
CREATE INDEX IF NOT EXISTS "DeliveryEmergencyOverride_expiresAt_status_idx" ON "DeliveryEmergencyOverride"("expiresAt","status");
